/* ---------------------------------------------------------------- helpers */
static void logf_(const pb_host *h, const char *fmt, ...)
{
    char b[700];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(b, sizeof b, fmt, ap);
    va_end(ap);
    h->log(b);
}

static void add(pb_results *R, const char *key, double v, const char *unit, uint64_t check, int32_t has_check)
{
    if (R->n >= PB_MAX_RESULTS) return;
    pb_res *r = &R->r[R->n++];
    memset(r, 0, sizeof *r);
    snprintf(r->key, sizeof r->key, "%s", key);
    r->v = v;
    snprintf(r->unit, sizeof r->unit, "%s", unit);
    r->check = check;
    r->has_check = has_check;
}

const pb_res *pb_find(const pb_results *R, const char *key)
{
    for (int32_t i = 0; i < R->n; ++i)
        if (!strcmp(R->r[i].key, key)) return &R->r[i];
    return NULL;
}

/* " | mac 12.3 us = 81.2x | check ok" for the Vita host; "" on the Mac */
static const char *vs_mac(const pb_host *h, const char *key, double v, uint64_t check, int32_t has_check)
{
    static char out[160];
    out[0] = 0;
    if (!h->ref) return out;
    double rv = 0.0;
    uint64_t rc = 0;
    int32_t rh = 0;
    if (!h->ref(key, &rv, &rc, &rh)) { snprintf(out, sizeof out, " | mac -"); return out; }
    int k = 0;
    if (rv > 0.0 && v > 0.0) k += snprintf(out + k, sizeof out - k, " | mac %.4g = %.1fx", rv, v / rv);
    if (has_check && rh) snprintf(out + k, sizeof out - k, " | %s", check == rc ? "check ok" : "CHECK MISMATCH vs mac");
    return out;
}

static char g_key[64];
static const char *K(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(g_key, sizeof g_key, fmt, ap);
    va_end(ap);
    return g_key;
}

static int cmp_u64(const void *a, const void *b)
{
    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;
    return x < y ? -1 : x > y;
}

static uint64_t g_dur[2048];
static sp_event g_ev[2048];
static sp_contact g_ct[4096];

void pb_bench_header(const pb_host *h)
{
    int32_t sizes[SP_ABI_N_SIZES];
    float probe = 0.0f;
    int32_t abi = sp_abi(sizes, SP_ABI_N_SIZES, &probe);
    logf_(h, "BENCH %s | libshepphys: %s", PB_BENCH_VERSION, sp_build_info());
    logf_(h, "BENCH abi %ld probe %s | T1 goldens: %s", (long)abi, probe == SHEPPHYS_ABI_PROBE ? "ok" : "BAD", sp_t1_golden_info());
    float s1 = sp_sinf(1.0f), c1 = sp_cosf(1.0f);
    uint32_t sb, cb;
    memcpy(&sb, &s1, 4);
    memcpy(&cb, &c1, 4);
    logf_(h, "BENCH sp_sinf(1) %08lx sp_cosf(1) %08lx (expected 3f576aa4 / 3f0a5140) | platform %s", (unsigned long)sb,
          (unsigned long)cb, pb_plat_name());
}

/* ---------------------------------------------------------------- T1 against the goldens */
typedef struct {
    const uint32_t *g;
    uint32_t gn, pos;
    int32_t rec, struct_div, first_diff, diff_recs, int_diffs, float_diffs;
    uint32_t first_tag, max_ulp, first_ulp;   /* first_ulp: the largest float difference inside the first differing record */
    int32_t first_a, first_b;
} t1cmp;

static uint32_t ulp_diff(uint32_t x, uint32_t y)
{
    int64_t ox = (x & 0x80000000u) ? -(int64_t)(x & 0x7FFFFFFFu) : (int64_t)x;
    int64_t oy = (y & 0x80000000u) ? -(int64_t)(y & 0x7FFFFFFFu) : (int64_t)y;
    int64_t d = ox > oy ? ox - oy : oy - ox;
    return d > 0xFFFFFFFFll ? 0xFFFFFFFFu : (uint32_t)d;
}

static void t1_cb(void *u, uint32_t tag, int32_t a, int32_t b, const uint32_t *w, int32_t n, uint32_t fmask)
{
    t1cmp *c = (t1cmp *)u;
    int32_t idx = c->rec++;
    if (c->struct_div >= 0) return;
    const uint32_t *g = c->g + c->pos;
    if (c->pos + 4 > c->gn || g[0] != tag || (int32_t)g[1] != a || (int32_t)g[2] != b || (int32_t)g[3] != n ||
        c->pos + 4 + (uint32_t)n > c->gn) {
        c->struct_div = idx;
        return;
    }
    int differs = 0;
    uint32_t rec_ulp = 0;
    for (int32_t i = 0; i < n; ++i) {
        uint32_t x = w[i], y = g[4 + i];
        if (x == y) continue;
        differs = 1;
        if ((fmask >> i) & 1u) {
            uint32_t d = ulp_diff(x, y);
            if (d > c->max_ulp) c->max_ulp = d;
            if (d > rec_ulp) rec_ulp = d;
            c->float_diffs++;
        } else c->int_diffs++;
    }
    if (differs) {
        if (c->first_diff < 0) {
            c->first_diff = idx; c->first_tag = tag; c->first_a = a; c->first_b = b; c->first_ulp = rec_ulp;
        }
        c->diff_recs++;
    }
    c->pos += 4 + (uint32_t)n;
}

int32_t pb_bench_t1(const pb_host *h, pb_results *R)
{
    int32_t n = sp_t1_count(), exact = 0;
    logf_(h, "T1 %d scenarios vs the Mac goldens (record by record: %d golden records compiled in)", (int)n, (int)PB_T1G_RECORDS);
    for (int32_t i = 0; i < n && !(h->stop && h->stop()); ++i) {
        const char *name = sp_t1_name(i);
        int32_t gi = -1;
        for (int32_t k = 0; k < PB_T1G_N; ++k) if (!strcmp(k_pb_t1g[k].name, name)) gi = k;
        sp_t1_result r, e, r2;
        uint64_t t0 = pb_now_ns();
        sp_t1_run(i, NULL, NULL, &r);
        uint64_t dt = pb_now_ns() - t0;
        int32_t have = sp_t1_expected(i, &e);
        int32_t hash_ok = have && e.hash_lo == r.hash_lo && e.hash_hi == r.hash_hi && r.status == 0;
        t1cmp c;
        memset(&c, 0, sizeof c);
        c.struct_div = c.first_diff = -1;
        if (gi >= 0) { c.g = k_pb_t1g_words + k_pb_t1g[gi].off; c.gn = k_pb_t1g[gi].nwords; }
        sp_t1_run(i, t1_cb, &c, &r2);
        if (gi < 0) c.struct_div = 0;
        else if (c.struct_div < 0 && (uint32_t)c.rec != k_pb_t1g[gi].nrec) c.struct_div = c.rec;
        int32_t is_exact = hash_ok && c.diff_recs == 0 && c.struct_div < 0;
        exact += is_exact;
        uint64_t hh = ((uint64_t)r.hash_hi << 32) | r.hash_lo;
        double us = (double)dt / 1000.0;
        add(R, K("t1.%s", name), us, "us", hh, 1);
        if (is_exact)
            logf_(h, "T1 %-3s %-16s EXACT    hash %016llx  %ld recs %ld steps  %9.1f us  %7.2f us/step%s", h->tag, name,
                  (unsigned long long)hh, (long)r.records, (long)r.steps, us, r.steps ? us / r.steps : 0.0,
                  vs_mac(h, K("t1.%s", name), us, hh, 1));
        else {
            char fd[48] = "-";
            if (c.first_diff >= 0)
                snprintf(fd, sizeof fd, "%ld %c%c%c%c %ld %ld", (long)c.first_diff, (int)(c.first_tag & 0xFF),
                         (int)((c.first_tag >> 8) & 0xFF), (int)((c.first_tag >> 16) & 0xFF), (int)(c.first_tag >> 24),
                         (long)c.first_a, (long)c.first_b);
            logf_(h, "T1 %-3s %-16s DIFFERS  hash %016llx (golden %08lx%08lx) | first diff: rec %s, %lu ulp there | %ld of %ld "
                  "recs differ (%ld float words, max %lu ulp; %ld int words) | records diverge structurally at %ld (-1 never) | "
                  "%.1f us",
                  h->tag, name, (unsigned long long)hh, (unsigned long)e.hash_hi, (unsigned long)e.hash_lo, fd,
                  (unsigned long)c.first_ulp, (long)c.diff_recs, (long)c.rec, (long)c.float_diffs, (unsigned long)c.max_ulp,
                  (long)c.int_diffs, (long)c.struct_div, us);
        }
    }
    add(R, "t1.exact", (double)exact, "", (uint64_t)exact, 1);
    logf_(h, "T1 %s RESULT %ld/%ld bit-exact vs the Mac goldens", h->tag, (long)exact, (long)n);
    return exact;
}

/* ---------------------------------------------------------------- STEP: the plan's scenes through libshepphys */
static void scene_one(const pb_host *h, pb_results *R, int32_t id)
{
    static pb_scene s;
    const char *nm = pb_scene_name(id);
    int32_t w = pb_shim_world_create();
    if (w <= 0) { logf_(h, "STEP %s FAIL world %ld", nm, (long)w); return; }
    if (pb_scene_build(&s, id, pb_shim_ops(), &w) != 0) {
        logf_(h, "STEP %s FAIL build %ld", nm, (long)s.status);
        sp_world_destroy(w);
        return;
    }
    const sp_step_def sd = {PB_DT, 8, 3, 0};
    int32_t steps = h->quick ? 100 : PB_MEASURE_STEPS;
    for (int32_t i = 0; i < PB_WARMUP_STEPS; ++i) { pb_scene_advance(&s); sp_events(w, g_ev, 2048); }
    uint64_t sum = 0, drive = 0, post = 0;
    int64_t ev = 0, touch = 0, c_all = 0, c_sens = 0, c_stouch = 0, c_otouch = 0, nsamp = 0;
    for (int32_t i = 0; i < steps; ++i) {
        uint64_t t0 = pb_now_ns();
        pb_scene_drive(&s);
        uint64_t t1 = pb_now_ns();
        sp_world_step(w, &sd, NULL);
        uint64_t t2 = pb_now_ns();
        int32_t ne = sp_events(w, g_ev, 2048);
        int32_t nt = sp_contacts(w, g_ct, 4096, SP_CONTACTS_TOUCHING_ONLY);
        uint64_t t3 = pb_now_ns();
        s.steps++;
        g_dur[i] = t2 - t1;
        sum += t2 - t1;
        drive += t1 - t0;
        post += t3 - t2;
        ev += ne;
        touch += nt;
        if (i % 10 == 0) {   /* untimed sample of the contact mix */
            int32_t nc = sp_contacts(w, g_ct, 4096, 0);
            c_all += nc;
            for (int32_t k = 0; k < nc && k < 4096; ++k) {
                int32_t se = (g_ct[k].flags & SP_CF_SENSOR) != 0, to = (g_ct[k].flags & SP_CF_TOUCHING) != 0;
                c_sens += se;
                c_stouch += se && to;
                c_otouch += !se && to;
            }
            nsamp++;
        }
    }
    uint64_t hash = 0xcbf29ce484222325ULL;
    pb_scene_hash(&s, &hash);
    sp_step_stats ss;
    pb_scene_drive(&s);
    sp_world_step(w, &sd, &ss);   /* one more step, for the body / proxy statistics (after the hash) */
    sp_world_destroy(w);
    qsort(g_dur, (size_t)steps, sizeof g_dur[0], cmp_u64);
    double mean = (double)sum / steps / 1000.0, med = g_dur[steps / 2] / 1000.0, p90 = g_dur[steps * 9 / 10] / 1000.0,
           mx = g_dur[steps - 1] / 1000.0, dr = (double)drive / steps / 1000.0, po = (double)post / steps / 1000.0;
    double ns = nsamp ? (double)nsamp : 1.0;
    logf_(h, "STEP %-3s %-17s shapes %ld (%ld sensors; %ld static, %ld on bodies; %ld chain edges) | bodies %ld: %ld dynamic, "
          "%ld kinematic, %ld kinematic-as-dynamic sensors; awake %ld; proxies %ld tree height %ld",
          h->tag, pb_scene_name(id), (long)s.n_shapes, (long)s.n_sensors, (long)s.n_static, (long)s.n_on_bodies,
          (long)s.n_chain_edges, (long)ss.bodies, (long)s.n_dyn, (long)s.n_kin, (long)s.n_emul, (long)ss.awake_bodies,
          (long)ss.proxies, (long)ss.tree_height);
    logf_(h, "STEP %-3s %-17s per step: %.1f contacts (%.1f sensor, %.1f sensor touching, %.1f solid touching), %.2f begin/end "
          "events, %.1f touching listed",
          h->tag, pb_scene_name(id), c_all / ns, c_sens / ns, c_stouch / ns, c_otouch / ns, (double)ev / steps,
          (double)touch / steps);
    logf_(h, "STEP %-3s %-17s step mean %8.1f us  med %8.1f  p90 %8.1f  max %8.1f | L30 tick (1.67 steps) %.3f ms%s", h->tag,
          nm, mean, med, p90, mx, mean * (50.0 / 30.0) / 1000.0, vs_mac(h, K("step.%s.mean", nm), mean, 0, 0));
    logf_(h, "STEP %-3s %-17s drive %6.1f us/step (script writes: ~%ld get_pose + set_velocity / teleport calls)%s", h->tag,
          nm, dr, (long)(2 * (s.nunit + s.nhit + s.nnpc + s.nproj + 2)), vs_mac(h, K("drive.%s", nm), dr, 0, 0));
    logf_(h, "STEP %-3s %-17s post  %6.1f us/step (drain events + list touching contacts with world manifolds)%s", h->tag, nm,
          po, vs_mac(h, K("post.%s", nm), po, 0, 0));
    logf_(h, "STEP %-3s %-17s pose hash %016llx%s", h->tag, nm, (unsigned long long)hash,
          vs_mac(h, K("hash.%s", nm), 0.0, hash, 1));
    add(R, K("step.%s.mean", nm), mean, "us", 0, 0);
    add(R, K("step.%s.med", nm), med, "us", 0, 0);
    add(R, K("step.%s.p90", nm), p90, "us", 0, 0);
    add(R, K("step.%s.max", nm), mx, "us", 0, 0);
    add(R, K("drive.%s", nm), dr, "us", 0, 0);
    add(R, K("post.%s", nm), po, "us", 0, 0);
    add(R, K("hash.%s", nm), 0.0, "", hash, 1);
    add(R, K("contacts.%s", nm), c_all / ns, "", 0, 0);
}

void pb_bench_scenes(const pb_host *h, pb_results *R)
{
    logf_(h, "STEP the plan's scenes through libshepphys: %d warm-up + %d measured steps of 0.02 s, 8/3 iterations",
          PB_WARMUP_STEPS, h->quick ? 100 : PB_MEASURE_STEPS);
    for (int32_t id = 0; id < PB_SC_N && !(h->stop && h->stop()); ++id) scene_one(h, R, id);
}

/* ---------------------------------------------------------------- B2: the same scenes on Box2D directly */
void pb_bench_b2(const pb_host *h, pb_results *R)
{
    static const int32_t ids[2] = {PB_SC_INTRO, PB_SC_BASE_NEVER};
    static pb_scene s;
    for (int32_t k = 0; k < 2 && !(h->stop && h->stop()); ++k) {
        int32_t id = ids[k];
        const char *nm = pb_scene_name(id);
        pb_b2world *W = pb_b2_create();
        if (!W || pb_scene_build(&s, id, pb_b2_ops(), W) != 0) { logf_(h, "B2 %s FAIL build", nm); pb_b2_destroy(W); continue; }
        int32_t steps = h->quick ? 100 : PB_MEASURE_STEPS;
        for (int32_t i = 0; i < PB_WARMUP_STEPS; ++i) pb_scene_advance(&s);
        uint64_t sum = 0;
        double prof[8] = {0}, p[8];
        float pf[8];
        for (int32_t i = 0; i < steps; ++i) {
            pb_scene_drive(&s);
            uint64_t t0 = pb_now_ns();
            s.ops->step(s.u);
            sum += pb_now_ns() - t0;
            s.steps++;
            pb_b2_profile(W, pf);
            for (int j = 0; j < 8; ++j) prof[j] += pf[j];
        }
        uint64_t hash = 0xcbf29ce484222325ULL;
        pb_scene_hash(&s, &hash);
        pb_b2_destroy(W);
        double mean = (double)sum / steps / 1000.0;
        for (int j = 0; j < 8; ++j) p[j] = prof[j] / steps * 1000.0;   /* ms -> us per step */
        const pb_res *shim = pb_find(R, K("step.%s.mean", nm));
        const pb_res *sh = pb_find(R, K("hash.%s", nm));
        logf_(h, "B2   %-3s %-17s Box2D direct step mean %8.1f us (libshepphys %s%.1f us: shim + listener %+.1f%%) | pose hash %016llx %s%s",
              h->tag, nm, mean, shim ? "" : "-", shim ? shim->v : 0.0, shim && shim->v > 0 ? 100.0 * (shim->v - mean) / mean : 0.0,
              (unsigned long long)hash, sh ? (sh->check == hash ? "= libshepphys hash" : "!= libshepphys HASH") : "",
              vs_mac(h, K("b2step.%s.mean", nm), mean, hash, 1));
        if (p[0] > 0.0)
            logf_(h, "B2   %-3s %-17s b2Profile per step (timers on): step %.2f us = collide %.2f + solve %.2f; solve = islands "
                  "%.2f (init %.2f, velocity %.2f, position %.2f) + synchronize fixtures & find new pairs %.2f + island search, "
                  "sleep and the timers themselves %.2f", h->tag, nm, p[0], p[1], p[2], p[3] + p[4] + p[5], p[3], p[4], p[5], p[6],
                  p[2] - p[3] - p[4] - p[5] - p[6]);
        else
            logf_(h, "B2   %-3s %-17s b2Profile: off in this binary (b2Timer is a no-op, as in Box2D's Vita build)", h->tag, nm);
        add(R, K("b2step.%s.mean", nm), mean, "us", hash, 1);
        if (p[0] > 0.0) {
            add(R, K("b2prof.%s.collide", nm), p[1], "us", 0, 0);
            add(R, K("b2prof.%s.solve", nm), p[2], "us", 0, 0);
            add(R, K("b2prof.%s.broadphase", nm), p[6], "us", 0, 0);
        }
    }
}

/* ---------------------------------------------------------------- CALL: C-side cost per call */
typedef int32_t (*fn_v)(void);
typedef int32_t (*fn_pose)(int32_t, int32_t, sp_pose *);
typedef int32_t (*fn_f3)(int32_t, int32_t, const float *);
typedef int32_t (*fn_apply)(int32_t, int32_t, int32_t, const float *, int32_t);
typedef int32_t (*fn_poses)(int32_t, sp_pose *, int32_t);
typedef int32_t (*fn_ray)(int32_t, const sp_ray_query *, sp_ray_hit *, int32_t);
typedef int32_t (*fn_ovl)(int32_t, const sp_shape_def *, const float *, const float *, uint32_t, int32_t, int32_t *, int32_t);
typedef int32_t (*fn_pt)(int32_t, const float *, uint32_t, int32_t *, int32_t);
typedef int32_t (*fn_aabb)(int32_t, const sp_aabb_query *, int32_t *, int32_t);
typedef int32_t (*fn_ct)(int32_t, sp_contact *, int32_t, int32_t);

static volatile int32_t g_sink;

#define TIMEIT(per, reps, ...)                                           \
    do {                                                                 \
        uint64_t best_ = ~0ull;                                          \
        for (int32_t rep_ = 0; rep_ < 3; ++rep_) {                       \
            uint64_t t0_ = pb_now_ns();                                  \
            for (int32_t i = 0; i < (reps); ++i) { __VA_ARGS__; }        \
            uint64_t d_ = pb_now_ns() - t0_;                             \
            if (d_ < best_) best_ = d_;                                  \
        }                                                                \
        per = (double)best_ / (double)(reps);                            \
    } while (0)

static void call_line(const pb_host *h, pb_results *R, const char *name, double ns, const char *what)
{
    logf_(h, "CALL %-3s %-22s %10.1f ns  %s%s", h->tag, name, ns, what, vs_mac(h, K("call.%s", name), ns, 0, 0));
    add(R, K("call.%s", name), ns, "ns", 0, 0);
}

void pb_bench_calls(const pb_host *h, pb_results *R)
{
    static pb_scene s;
    static sp_ray_query rays[256];
    static sp_ray_hit hits[64];
    static float pts[2 * 1024];
    static sp_pose poses[PB_MAX_BODIES];
    int32_t out[16];
    logf_(h, "CALL C-side cost per libshepphys call (through shepphys_proc pointers, as a binding calls them) on the "
          "intro_fight world after 150 steps. NOTE: the managed<->native glue (interpreted stub, icall, P/Invoke, boxing) "
          "CANNOT be measured in this pure C app; it is measured later by the Mono-based apps' physbench mode. These are the "
          "native floors under it.");
    int32_t w = pb_shim_world_create();
    if (w <= 0 || pb_scene_build(&s, PB_SC_INTRO, pb_shim_ops(), &w) != 0) { logf_(h, "CALL FAIL build"); return; }
    for (int32_t i = 0; i < 150; ++i) { pb_scene_advance(&s); sp_events(w, g_ev, 2048); }
    fn_v f_ver = (fn_v)shepphys_proc("sp_version");
    fn_pose f_pose = (fn_pose)shepphys_proc("sp_body_get_pose");
    fn_f3 f_vel = (fn_f3)shepphys_proc("sp_body_set_velocity");
    fn_f3 f_xf = (fn_f3)shepphys_proc("sp_body_set_transform");
    fn_apply f_apply = (fn_apply)shepphys_proc("sp_body_apply");
    fn_poses f_poses = (fn_poses)shepphys_proc("sp_poses");
    fn_ray f_ray = (fn_ray)shepphys_proc("sp_raycast");
    fn_ovl f_ovl = (fn_ovl)shepphys_proc("sp_overlap_shape");
    fn_pt f_pt = (fn_pt)shepphys_proc("sp_query_point");
    fn_aabb f_aabb = (fn_aabb)shepphys_proc("sp_query_aabb");
    fn_ct f_ct = (fn_ct)shepphys_proc("sp_contacts");
    if (!f_ver || !f_pose || !f_vel || !f_xf || !f_apply || !f_poses || !f_ray || !f_ovl || !f_pt || !f_aabb || !f_ct) {
        logf_(h, "CALL FAIL shepphys_proc lookup");
        sp_world_destroy(w);
        return;
    }
    int32_t q = h->quick ? 10 : 1;
    double v;
    uint32_t rng = 0x1234567u;
    int32_t nr = pb_scene_rays(&s, rays, 256, &rng);
    pb_scene_points(&s, pts, 1024, &rng);
    int32_t u0 = s.unit[0], hb = s.hit[0];
    sp_pose p0;
    sp_body_get_pose(w, u0, &p0);
    float vel[3] = {p0.vx, p0.vy, 0.0f}, zero[2] = {0.0f, 0.0f};

    TIMEIT(v, 100000 / q, g_sink += f_ver());
    call_line(h, R, "nop", v, "sp_version: an empty native entry (call + return)");
    TIMEIT(v, 20000 / q, { sp_pose p; g_sink += f_pose(w, s.lamb, &p); });
    call_line(h, R, "get_pose", v, "sp_body_get_pose (rb.position / velocity read, 0 calls once the mirror exists)");
    TIMEIT(v, 20000 / q, g_sink += f_vel(w, u0, vel));
    call_line(h, R, "set_velocity", v, "sp_body_set_velocity (MovePosition target -> velocity)");
    TIMEIT(v, 20000 / q, g_sink += f_apply(w, u0, SP_APPLY_FORCE, zero, 0));
    call_line(h, R, "apply_force", v, "sp_body_apply force (AddForce)");
    {
        sp_pose hp;
        sp_body_get_pose(w, hb, &hp);
        float a[3] = {hp.x, hp.y, hp.angle}, b2[3] = {hp.x + 0.3f, hp.y, hp.angle};
        TIMEIT(v, 4000 / q, g_sink += f_xf(w, hb, a));
        call_line(h, R, "teleport_still", v, "sp_body_set_transform to the same pose (synchronize 1 proxy, no tree move)");
        TIMEIT(v, 200 / q, g_sink += f_xf(w, hb, (i & 1) ? a : b2));
        call_line(h, R, "teleport_move", v, "sp_body_set_transform 0.3 u back and forth (proxy leaves its fat AABB: tree move)");
        f_xf(w, hb, a);
    }
    int32_t nb = sp_poses(w, poses, PB_MAX_BODIES);
    TIMEIT(v, 4000 / q, g_sink += f_poses(w, poses, PB_MAX_BODIES));
    call_line(h, R, "poses_all", v, "sp_poses: every body's pose in one call");
    call_line(h, R, "poses_per_body", v / (nb > 0 ? nb : 1), "  ... per body");
    TIMEIT(v, 8 * nr / q, g_sink += f_ray(w, &rays[i % nr], hits, 1));
    call_line(h, R, "ray_closest", v, "sp_raycast closest, Obstacles|Island (LOS checks unit->Lamb + 2-12 u wall probes)");
    {
        sp_ray_query ra[256];
        for (int32_t k = 0; k < nr; ++k) { ra[k] = rays[k]; ra[k].mask_bits = 0xFFFF; ra[k].flags = SP_RAY_ALL | SP_RAY_SORTED; }
        TIMEIT(v, 4 * nr / q, g_sink += f_ray(w, &ra[i % nr], hits, 64));
        call_line(h, R, "ray_all_sorted", v, "sp_raycast all layers, all hits sorted (RaycastAll)");
    }
    sp_shape_def c;
    memset(&c, 0, sizeof c);
    c.kind = SP_SHAPE_CIRCLE;
    c.radius = 0.375f;
    TIMEIT(v, 2048 / q, {
        float xf[3] = {pts[2 * (i & 1023)], pts[2 * (i & 1023) + 1], 0.0f};
        g_sink += f_ovl(w, &c, NULL, xf, PB_R_OBST | PB_R_WALL, SP_QUERY_SKIP_SENSORS, out, 4);
    });
    call_line(h, R, "overlap_circle", v, "sp_overlap_shape circle r 0.375, Obstacles|Island, no triggers (A* node test)");
    c.radius = 1.0f;
    TIMEIT(v, 2048 / q, {
        float xf[3] = {pts[2 * (i & 1023)], pts[2 * (i & 1023) + 1], 0.0f};
        g_sink += f_ovl(w, &c, NULL, xf, 0xFFFF, 0, out, 16);
    });
    call_line(h, R, "overlap_circle_all", v, "sp_overlap_shape circle r 1, every layer incl. triggers (OverlapCircleAll)");
    TIMEIT(v, 4096 / q, g_sink += f_pt(w, &pts[2 * (i & 1023)], 0xFFFF, out, 16));
    call_line(h, R, "query_point", v, "sp_query_point every layer (OverlapPoint)");
    TIMEIT(v, 4096 / q, {
        float x = pts[2 * (i & 1023)], y = pts[2 * (i & 1023) + 1];
        sp_aabb_query aq = {x - 1.0f, y - 1.0f, x + 1.0f, y + 1.0f, 0xFFFF, 0};
        g_sink += f_aabb(w, &aq, out, 16);
    });
    call_line(h, R, "query_aabb", v, "sp_query_aabb 2 x 2 (broadphase only)");
    int32_t ntc = sp_contacts(w, NULL, 0, SP_CONTACTS_TOUCHING_ONLY);
    TIMEIT(v, 1000 / q, g_sink += f_ct(w, g_ct, 4096, SP_CONTACTS_TOUCHING_ONLY));
    call_line(h, R, "contacts_touching", v, "sp_contacts touching (the per-step Stay list, with world manifolds)");
    call_line(h, R, "contacts_per_contact", v / (ntc > 0 ? ntc : 1), "  ... per touching contact");
    {   /* render poses: lerp(prev, cur, alpha) for 48 interpolated bodies (native, per display frame) */
        static float prev[48 * 3], cur[48 * 3], o[48 * 3];
        for (int32_t k = 0; k < 48 * 3; ++k) { prev[k] = (float)k * 0.25f; cur[k] = prev[k] + 0.11f; }
        float alpha = 0.37f;
        TIMEIT(v, 4000 / q, {
            for (int32_t k = 0; k < 48 * 3; ++k) o[k] = prev[k] + (cur[k] - prev[k]) * alpha;
            alpha = o[i % (48 * 3)] > 1e9f ? 0.5f : alpha;
        });
        call_line(h, R, "lerp_per_body", v / 48.0, "render pose lerp (x, y, angle) per interpolated body, native");
    }
    logf_(h, "CALL %-3s (state: %ld bodies, %ld touching contacts, %ld rays, sink %ld)", h->tag, (long)nb, (long)ntc, (long)nr,
          (long)g_sink);
    sp_world_destroy(w);
}

/* ---------------------------------------------------------------- ASTAR: grid scans */
static int32_t shim_scan(int32_t w, const pb_scene *s, int32_t *blocked)
{
    sp_shape_def c;
    memset(&c, 0, sizeof c);
    c.kind = SP_SHAPE_CIRCLE;
    c.radius = s->gr;
    int32_t out[4], nb = 0;
    for (int32_t y = 0; y < s->gh; ++y)
        for (int32_t x = 0; x < s->gw; ++x) {
            float xf[3] = {s->gx0 + s->gstep * (float)x, s->gy0 + s->gstep * (float)y, 0.0f};
            nb += sp_overlap_shape(w, &c, NULL, xf, s->gmask, SP_QUERY_SKIP_SENSORS, out, 4) > 0 ? 1 : 0;
        }
    *blocked = nb;
    return s->gw * s->gh;
}

void pb_bench_astar(const pb_host *h, pb_results *R)
{
    static const int32_t ids[2] = {PB_SC_INTRO, PB_SC_BASE_NEVER};
    static pb_scene s, s2;
    logf_(h, "ASTAR GridGraph-shaped scans: one OverlapCircle per node (r 0.375 room / 0.25 base, no triggers), C side only");
    for (int32_t k = 0; k < 2 && !(h->stop && h->stop()); ++k) {
        int32_t id = ids[k];
        const char *nm = pb_scene_name(id);
        int32_t w = pb_shim_world_create();
        pb_b2world *W = pb_b2_create();
        if (w <= 0 || !W || pb_scene_build(&s, id, pb_shim_ops(), &w) != 0 || pb_scene_build(&s2, id, pb_b2_ops(), W) != 0) {
            logf_(h, "ASTAR %s FAIL build", nm);
            if (w > 0) sp_world_destroy(w);
            pb_b2_destroy(W);
            continue;
        }
        for (int32_t i = 0; i < 100; ++i) { pb_scene_advance(&s); pb_scene_advance(&s2); sp_events(w, g_ev, 2048); }
        int32_t b1 = 0, b2 = 0, n = 0;
        uint64_t best1 = ~0ull, best2 = ~0ull;
        for (int32_t rep = 0; rep < (h->quick ? 1 : 2); ++rep) {
            uint64_t t0 = pb_now_ns();
            n = shim_scan(w, &s, &b1);
            uint64_t t1 = pb_now_ns();
            pb_b2_astar(W, &s2, &b2);
            uint64_t t2 = pb_now_ns();
            if (t1 - t0 < best1) best1 = t1 - t0;
            if (t2 - t1 < best2) best2 = t2 - t1;
        }
        double ms1 = best1 / 1e6, ms2 = best2 / 1e6;
        logf_(h, "ASTAR %-3s %-12s %ldx%ld = %ld nodes, %ld blocked | libshepphys sp_overlap_shape %8.2f ms (%.2f us/node)%s",
              h->tag, nm, (long)s.gw, (long)s.gh, (long)n, (long)b1, ms1, best1 / 1000.0 / n,
              vs_mac(h, K("astar.%s.shim", nm), ms1, (uint64_t)b1, 1));
        logf_(h, "ASTAR %-3s %-12s child-aware broadphase prototype (Stage 2/5 query shape) %8.2f ms (%.2f us/node), "
              "%ld blocked %s%s", h->tag, nm, ms2, best2 / 1000.0 / n, (long)b2, b1 == b2 ? "(= shim)" : "(!= shim: BUG)",
              vs_mac(h, K("astar.%s.child", nm), ms2, (uint64_t)b2, 1));
        add(R, K("astar.%s.shim", nm), ms1, "ms", (uint64_t)b1, 1);
        add(R, K("astar.%s.child", nm), ms2, "ms", (uint64_t)b2, 1);
        sp_world_destroy(w);
        pb_b2_destroy(W);
    }
}

/* ---------------------------------------------------------------- threads: FJ, NP, MW */
static void nop_task(void *c, int32_t p, int32_t n) { (void)c; (void)p; (void)n; }

static void fj_case(const pb_host *h, pb_results *R, int32_t mode, int32_t nw, int32_t cold)
{
    int32_t runs = h->quick ? 100 : (cold ? 200 : mode == PB_POOL_BLOCK ? 1000 : 2000);
    if (pb_pool_init(nw, mode, h->fpscr, 50) != 0) { logf_(h, "FJ FAIL pool init (%s, %ld workers)", pb_pool_mode_name(mode), (long)nw); return; }
    for (int32_t i = 0; i < 50; ++i) pb_pool_run(nop_task, NULL, nw + 1);
    uint64_t sum = 0;
    for (int32_t i = 0; i < runs; ++i) {
        if (cold) pb_sleep_us(2000);
        uint64_t t0 = pb_now_ns();
        pb_pool_run(nop_task, NULL, nw + 1);
        g_dur[i] = pb_now_ns() - t0;
        sum += g_dur[i];
    }
    pb_pool_shutdown();
    qsort(g_dur, (size_t)runs, sizeof g_dur[0], cmp_u64);
    double mean = (double)sum / runs / 1000.0;
    const char *mn = cold ? "hybrid_cold" : pb_pool_mode_name(mode);
    logf_(h, "FJ   %-3s %-11s %ld threads: fork+join %7.2f us mean, med %7.2f, p90 %7.2f, max %8.2f (%ld runs)%s", h->tag, mn,
          (long)(nw + 1), mean, g_dur[runs / 2] / 1000.0, g_dur[runs * 9 / 10] / 1000.0, g_dur[runs - 1] / 1000.0, (long)runs,
          vs_mac(h, K("fj.%s.%ld", mn, (long)(nw + 1)), mean, 0, 0));
    add(R, K("fj.%s.%ld", mn, (long)(nw + 1)), mean, "us", 0, 0);
}

static void np_task(void *ctx, int32_t part, int32_t nparts) { pb_np_part((pb_b2world *)ctx, part, nparts); }

typedef struct {
    pb_scene s;
    int32_t w;
    uint64_t ns, hash;
    int32_t steps;
} mw_t;
static mw_t g_mw[3];

static void mw_task(void *ctx, int32_t part, int32_t nparts)
{
    (void)ctx;
    (void)nparts;
    mw_t *m = &g_mw[part];
    uint64_t t0 = pb_now_ns();
    for (int32_t i = 0; i < m->steps; ++i) pb_scene_advance(&m->s);
    m->ns = pb_now_ns() - t0;
    uint64_t hh = 0xcbf29ce484222325ULL;
    pb_scene_hash(&m->s, &hh);
    m->hash = hh;
}

void pb_bench_threads(const pb_host *h, pb_results *R)
{
    int32_t maxw = h->workers < 2 ? h->workers : 2;
    if (maxw < 1) { logf_(h, "FJ no worker threads available"); return; }
    if (pb_pool_init(maxw, PB_POOL_SPIN, h->fpscr, 50) == 0) {
        pb_pool_run(nop_task, NULL, maxw + 1);
        logf_(h, "FJ   %-3s worker FPSCR at thread entry: %08lx / %08lx (caller %08lx; workers then set %08lx)", h->tag,
              (unsigned long)pb_pool_worker_fpscr0(1), (unsigned long)pb_pool_worker_fpscr0(2), (unsigned long)pb_fpscr_get(),
              (unsigned long)h->fpscr);
        pb_pool_shutdown();
    }
    /* FJ: what one fork + join costs (an empty phase), per wait strategy */
    for (int32_t nw = 1; nw <= maxw && !(h->stop && h->stop()); ++nw) {
        fj_case(h, R, PB_POOL_SPIN, nw, 0);
        fj_case(h, R, PB_POOL_BLOCK, nw, 0);
        fj_case(h, R, PB_POOL_HYBRID, nw, 0);
        fj_case(h, R, PB_POOL_HYBRID, nw, 1);
    }
    /* NP: the parallel collide / trigger phases, prototyped on the b2 backend; every split must be bit-identical */
    static const int32_t ids[2] = {PB_SC_INTRO, PB_SC_BASE_NEVER};
    for (int32_t k = 0; k < 2 && !(h->stop && h->stop()); ++k) {
        int32_t id = ids[k];
        const char *nm = pb_scene_name(id);
        uint64_t chain0 = 0;
        double serial = 0.0;
        /* -1: serial warm-up (unlogged); 0: serial; 1..maxw: spin with cfg workers; then block; last: serial again (the serial
         * figure is the better of the two, so a clock still ramping up -- the Mac's DVFS after the idle FJ cases -- does not
         * flatter the parallel runs; the Vita runs at a fixed clock) */
        for (int32_t cfg = -1; cfg <= 2 * maxw + 1; ++cfg) {   /* -1: an unlogged serial warm-up run */
            int32_t last = cfg == 2 * maxw + 1;
            int32_t nw = (last || cfg < 0) ? 0 : cfg <= maxw ? cfg : cfg - maxw;
            int32_t mode = (last || cfg <= maxw) ? PB_POOL_SPIN : PB_POOL_BLOCK;
            static pb_scene s;
            pb_b2world *W = pb_b2_create();
            if (!W || pb_scene_build(&s, id, pb_b2_ops(), W) != 0) { logf_(h, "NP %s FAIL build", nm); pb_b2_destroy(W); break; }
            if (nw > 0 && pb_pool_init(nw, mode, h->fpscr, 50) != 0) { logf_(h, "NP FAIL pool"); pb_b2_destroy(W); break; }
            for (int32_t i = 0; i < PB_WARMUP_STEPS; ++i) pb_scene_advance(&s);
            int32_t steps = h->quick ? 30 : 150;
            uint64_t phase = 0, prep = 0, chain = 0xcbf29ce484222325ULL;
            int64_t nsol = 0, nsen = 0;
            for (int32_t i = 0; i < steps; ++i) {
                pb_scene_advance(&s);
                uint64_t t0 = pb_now_ns();
                int32_t a = 0, b = 0;
                pb_np_prepare(W, &a, &b);
                pb_np_clear(W);
                uint64_t t1 = pb_now_ns();
                if (nw == 0) pb_np_part(W, 0, 1);
                else pb_pool_run(np_task, W, nw + 1);
                uint64_t t2 = pb_now_ns();
                prep += t1 - t0;
                phase += t2 - t1;
                nsol += a;
                nsen += b;
                uint64_t d = pb_np_digest(W);
                for (int j = 0; j < 8; ++j) { chain ^= (d >> (8 * j)) & 0xFF; chain *= 0x100000001b3ULL; }
            }
            if (nw > 0) pb_pool_shutdown();
            pb_b2_destroy(W);
            double us = (double)phase / steps / 1000.0;
            if (cfg < 0) { chain0 = chain; continue; }
            if (cfg == 0) {
                serial = us;
                if (chain != chain0) logf_(h, "NP   %-3s %-12s serial warm-up and serial run: slots DIFFER", h->tag, nm);
            }
            if (last) {   /* the second serial run: replace the serial figure if better, check it, no separate line */
                pb_res *r0 = (pb_res *)pb_find(R, K("np.%s.1", nm));
                if (us < serial && r0) r0->v = us;
                if (chain != chain0) logf_(h, "NP   %-3s %-12s second serial run: slots DIFFER from the first", h->tag, nm);
                logf_(h, "NP   %-3s %-12s serial again: %8.2f us/step (the serial figure is the better of %.2f / %.2f)", h->tag, nm,
                      us, serial, us);
                continue;
            }
            const char *key = K("np.%s.%ld%s", nm, (long)(nw + 1), mode == PB_POOL_BLOCK ? "b" : "");
            char kk[64];
            snprintf(kk, sizeof kk, "%s", key);
            logf_(h, "NP   %-3s %-12s %ld thread%s %-5s collide+trigger phase %8.2f us/step (serial %8.2f: %.2fx) | %.1f solid + "
                  "%.1f sensor contacts/step, snapshot %.2f us | slots %s%s",
                  h->tag, nm, (long)(nw + 1), nw ? "s" : " ", nw ? pb_pool_mode_name(mode) : "", us, serial,
                  us > 0 ? serial / us : 0.0, (double)nsol / steps, (double)nsen / steps, (double)prep / steps / 1000.0,
                  chain == chain0 ? "bit-identical to serial" : "DIFFER FROM SERIAL", vs_mac(h, kk, us, chain, 1));
            add(R, kk, us, "us", chain, 1);
        }
    }
    /* MW: 1..3 independent worlds stepped at once, one per core: the shared-L2 / memory slowdown, hashes must not change */
    for (int32_t n = 1; n <= maxw + 1 && !(h->stop && h->stop()); ++n) {
        int32_t okb = 1;
        for (int32_t p = 0; p < n; ++p) {
            g_mw[p].w = pb_shim_world_create();
            if (g_mw[p].w <= 0 || pb_scene_build(&g_mw[p].s, PB_SC_INTRO, pb_shim_ops(), &g_mw[p].w) != 0) okb = 0;
            for (int32_t i = 0; okb && i < PB_WARMUP_STEPS; ++i) pb_scene_advance(&g_mw[p].s);
            g_mw[p].steps = h->quick ? 60 : 300;
        }
        if (okb && (n == 1 || pb_pool_init(n - 1, PB_POOL_SPIN, h->fpscr, 50) == 0)) {
            if (n == 1) mw_task(NULL, 0, 1);
            else { pb_pool_run(mw_task, NULL, n); pb_pool_shutdown(); }
            double sum = 0.0;
            int32_t same = 1;
            for (int32_t p = 0; p < n; ++p) {
                sum += (double)g_mw[p].ns / g_mw[p].steps / 1000.0;
                same &= g_mw[p].hash == g_mw[0].hash;
            }
            double per = sum / n;
            const pb_res *solo = pb_find(R, "mw.1");
            logf_(h, "MW   %-3s %ld world%s on %ld core%s: %8.1f us/step per world (solo %8.1f: %.2fx) | hashes %s %016llx%s", h->tag,
                  (long)n, n > 1 ? "s" : " ", (long)n, n > 1 ? "s" : " ", per, solo ? solo->v : per, solo ? per / solo->v : 1.0,
                  same ? "all equal" : "DIFFER", (unsigned long long)g_mw[0].hash, vs_mac(h, K("mw.%ld", (long)n), per, g_mw[0].hash, 1));
            add(R, K("mw.%ld", (long)n), per, "us", g_mw[0].hash, 1);
        } else logf_(h, "MW FAIL setup (%ld worlds)", (long)n);
        for (int32_t p = 0; p < n; ++p) if (g_mw[p].w > 0) sp_world_destroy(g_mw[p].w);
    }
}

/* ---------------------------------------------------------------- summary */
void pb_bench_summary(const pb_host *h, const pb_results *R)
{
    char b[700];
    int k = snprintf(b, sizeof b, "SUMMARY %s", h->tag);
    static const char *const keys[][2] = {
        {"step.intro_fight.mean", "intro"}, {"step.intro_fight_stock.mean", "intro_stock"}, {"step.dungeon_room.mean", "dungeon"},
        {"step.base_never.mean", "base_never"}, {"step.base_sleep.mean", "base_sleep"}, {"call.get_pose", "get_pose_ns"},
        {"call.ray_closest", "ray_ns"}, {"call.overlap_circle", "overlap_ns"}, {"astar.intro_fight.shim", "astar_intro_ms"},
        {"astar.base_never.shim", "astar_base_ms"}, {"astar.base_never.child", "astar_base_child_ms"},
        {"fj.spin.3", "fj_spin3_us"}, {"fj.hybrid_cold.3", "fj_cold3_us"}, {"np.intro_fight.1", "np_intro_1t_us"},
        {"np.intro_fight.3", "np_intro_3t_us"}, {"np.base_never.1", "np_base_1t_us"}, {"np.base_never.3", "np_base_3t_us"},
        {"mw.1", "mw1_us"}, {"mw.3", "mw3_us"}, {"t1.exact", "t1_exact"},
    };
    for (unsigned i = 0; i < sizeof keys / sizeof keys[0] && k < (int)sizeof b - 40; ++i) {
        const pb_res *r = pb_find(R, keys[i][0]);
        if (r) k += snprintf(b + k, sizeof b - k, " %s=%.4g", keys[i][1], r->v);
    }
    h->log(b);
}
